SELECT id, direction_id, name, goal_summary, semester_goals_json, monthly_tasks_json, status
FROM task_template
WHERE deleted = 0

    AND direction_id = #{directionId}

ORDER BY ${sortColumn} ${sortDir}
LIMIT #{offset}, #{size}

mapper.update:
